import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007;

    static class ModularNumber {
        long value;

        ModularNumber(long v) {
            value = v % MOD;
            if (value < 0) value += MOD;
        }

        static long modInverse(long a, long m) {
            long g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                long q = g / r;
                long tmp = g % r;
                g = r;
                r = tmp;
                long x1 = x - q * y;
                x = y;
                y = x1;
            }
            return x < 0 ? x + m : x;
        }

        ModularNumber add(ModularNumber other) {
            long res = value + other.value;
            if (res >= MOD) res -= MOD;
            return new ModularNumber(res);
        }

        ModularNumber subtract(ModularNumber other) {
            long res = value - other.value;
            if (res < 0) res += MOD;
            return new ModularNumber(res);
        }

        ModularNumber multiply(ModularNumber other) {
            long res = (value * other.value) % MOD;
            return new ModularNumber(res);
        }

        ModularNumber divide(ModularNumber other) {
            return this.multiply(new ModularNumber(modInverse(other.value, MOD)));
        }

        ModularNumber inv() {
            return new ModularNumber(modInverse(value, MOD));
        }

        ModularNumber pow(long p) {
            ModularNumber base = this;
            ModularNumber result = new ModularNumber(1);
            while (p > 0) {
                if ((p & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        ModularNumber[][] prob = new ModularNumber[N][N];

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().split(" ");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                prob[i][j] = new ModularNumber(p).divide(new ModularNumber(100));
            }
        }

        List<List<Integer>> countByPopcount = new ArrayList<>();
        for (int i = 0; i <= N; i++) {
            countByPopcount.add(new ArrayList<>());
        }
        int[] lookup = new int[1 << N];
        Arrays.fill(lookup, -1);
        for (int m = 0; m < (1 << N); m++) {
            int c = Integer.bitCount(m);
            lookup[m] = countByPopcount.get(c).size();
            countByPopcount.get(c).add(m);
        }

        Map<Long, ModularNumber> currentStates = new HashMap<>();
        currentStates.put(1L << lookup[0], new ModularNumber(1));

        for (int layer = 0; layer < N; layer++) {
            Map<Long, ModularNumber> nextStates = new HashMap<>();
            for (int mask = 0; mask < (1 << N); mask++) {
                ModularNumber prod = new ModularNumber(1);
                for (int r = 0; r < N; r++) {
                    boolean bitSet = ((mask >> r) & 1) == 1;
                    if (bitSet) {
                        prod = prod.multiply(prob[layer][r]);
                    } else {
                        prod = prod.multiply(new ModularNumber(1).subtract(prob[layer][r]));
                    }
                }
                for (Map.Entry<Long, ModularNumber> p : currentStates.entrySet()) {
                    long msk = p.getKey();
                    ModularNumber pval = p.getValue();
                    long new_msk = 0;
                    for (int m : countByPopcount.get(layer)) {
                        if (((msk >> lookup[m]) & 1) == 1) {
                            for (int i = 0; i < N; i++) {
                                if (((mask >> i) & 1) == 1 && ((m >> i) & 1) == 0) {
                                    new_msk |= 1L << lookup[m | (1 << i)];
                                }
                            }
                        }
                    }
                    nextStates.put(new_msk, nextStates.getOrDefault(new_msk, new ModularNumber(0)).add(pval.multiply(prod)));
                }
            }
            currentStates = nextStates;
        }

        ModularNumber total = new ModularNumber(0);
        int last_idx = lookup[(1 << N) - 1];
        for (Map.Entry<Long, ModularNumber> p : currentStates.entrySet()) {
            if (((p.getKey() >> last_idx) & 1) == 1) {
                total = total.add(p.getValue());
            }
        }
        System.out.println((int) total.value);
    }
}
